select id, user_id AS userId, role, start_time AS startTime, spend_time AS spendTime, base_path AS basePath, uri, url, method, ip, parameter, result, description, service_order_id AS serviceOrderId, commission_order_id AS commissionOrderId, visa_id AS visaId, visa_official_id AS visaOfficialId, school_id AS schoolId, operated_user AS operatedUser from b_web_log where 1 = 1
AND service_order_id = #{serviceOrderId}
AND commission_order_id = #{commissionOrderId}
AND visa_id = #{visaId}
AND visa_official_id = #{visaOfficialId}
AND school_id = #{schoolId}
AND user_id = #{userId}
AND operated_user = #{operatedUser}
AND (uri LIKE '%login' or uri LIKE '%out')
ORDER BY id DESC LIMIT #{offset}, #{rows};

